// The same batch a re-run would fetch again. Keys are stable business
// identifiers - not row numbers, not timestamps, not a random UUID.
return [
  { json: { orderId: 'ORD-10042', amountCents: 4900 } },
  { json: { orderId: 'ORD-10043', amountCents: 12500 } },
  { json: { orderId: 'ORD-10044', amountCents: 800 } }
];

// Durable across executions of this workflow, unlike anything held in an
// item. This is what turns a re-run from 'do it all again' into 'finish
// what was left'.
const store = $getWorkflowStaticData('global');
store.processed = store.processed ?? {};

// Drop keys older than the replay window so the record cannot grow forever.
const WINDOW_MS = 7 * 24 * 60 * 60 * 1000;
const now = Date.now();
for (const [key, ts] of Object.entries(store.processed)) {
  if (now - ts > WINDOW_MS) delete store.processed[key];
}

const out = [];
let skipped = 0;

for (const item of $input.all()) {
  const key = `order:${item.json.orderId}`;
  if (store.processed[key]) { skipped++; continue; }

  // Claim the key BEFORE the side effect, not after. Writing it afterwards
  // leaves a window in which a crash between the POST and the write makes
  // the next run repeat the POST - the exact failure this guards against.
  store.processed[key] = now;
  out.push({ json: { ...item.json, idempotencyKey: key } });
}

if (out.length === 0) {
  return [{ json: { nothingToDo: true, skipped } }];
}
return out.map(o => ({ json: { ...o.json, skippedThisRun: skipped } }));

const items = $input.all();
const sent = items.filter(i => !i.json.nothingToDo).length;
const skipped = items[0]?.json?.skippedThisRun ?? items[0]?.json?.skipped ?? 0;
return [{ json: { sentThisRun: sent, skippedAsAlreadyDone: skipped } }];

// Items that still failed after retries. They keep their claimed key, so
// a blind re-run will NOT resend them - they need a deliberate replay.
// Route this to your alerting so a silent skip cannot pass for success.
return $input.all().map(item => ({
  json: {
    needsManualReplay: item.json.orderId ?? null,
    error: item.json.error?.message ?? item.json.error ?? 'unknown',
    howToReplay: 'Delete this key from workflow static data, then re-run.'
  }
}));
